record.field:
{
    "type": "object",
    "properties": {
        "product_id": {
            "type": "number",
            "description": "Id of the product, obtained with 'Find Product' (purpose purchase)."
        },
        "quantity": {
            "type": "number",
            "description": "Quantity needed, greater than 0."
        },
        "needed_date": {
            "type": "string",
            "description": "Date the goods are needed, YYYY-MM-DD (optional).",
            "maxLength": 10,
            "pattern": "\\d{4}-\\d{2}-\\d{2}"
        },
        "note": {
            "type": "string",
            "description": "Extra context for the team (optional).",
            "maxLength": 500
        }
    },
    "required": [
        "product_id",
        "quantity"
    ]
}

{
    "type": "object",
    "properties": {
        "order_id": {
            "type": "number",
            "description": "Id of the vendor's request for quotation (order_id from 'Get Request')."
        },
        "unit_price": {
            "type": "number",
            "description": "Unit price quoted by the vendor, in the currency of the request (greater than 0)."
        },
        "lead_days": {
            "type": "number",
            "description": "Delivery time in days if the vendor said it (optional)."
        },
        "conditions": {
            "type": "string",
            "description": "Other conditions the vendor stated: payment terms, minimum order, validity (optional).",
            "maxLength": 500
        }
    },
    "required": [
        "order_id",
        "unit_price"
    ]
}

{
    "type": "object",
    "properties": {
        "request_id": {
            "type": "number",
            "description": "Id of the buyer request."
        },
        "recommendation": {
            "type": "string",
            "description": "Recommendation in 4-8 lines: best option and why, alerts, missing replies.",
            "maxLength": 3000
        }
    },
    "required": [
        "request_id",
        "recommendation"
    ]
}
